
(function(){
  // ★★★ 硬编码开关：设为 true 则禁用 cat-boot.log，设为 false 则启用 ★★★
  var DISABLE_BOOT_LOG = true;   // 设为 true 可禁用 cat-boot.log（仅构建时生效）

  var firstBootLogWrite = true;
  var bootLogPath = '';
  function bootSafeString(value) {
    try { return String(value); } catch (_) { return '[unstringifiable]'; }
  }
  function bootBaseDir() {
    try {
      if (typeof process !== 'undefined' && process && process.env && process.env.NODE_PATH) {
        return process.env.NODE_PATH;
      }
    } catch (_) {}
    try {
      if (typeof process !== 'undefined' && process && typeof process.cwd === 'function') {
        return process.cwd();
      }
    } catch (_) {}
    return '.';
  }
  function bootLog(message) {
    // ★ 开关判断
    if (DISABLE_BOOT_LOG) return;

    try {
      var req = eval('require');
      var fs = req('fs');
      var path = req('path');
      if (!bootLogPath) bootLogPath = path.join(bootBaseDir(), 'cat-boot.log');
      var line = '[' + new Date().toISOString() + '] ' + bootSafeString(message) + '\n';
      fs.writeFileSync(bootLogPath, line, { flag: firstBootLogWrite ? 'w' : 'a' });
      firstBootLogWrite = false;
    } catch (_) {}
  }
  globalThis.__catpawBootLog = bootLog;
  bootLog('boot banner ran node=' + (typeof process !== 'undefined' && process ? process.version : 'unknown') + ' cwd=' + bootBaseDir());
})();

